            IF levelSensor >= 100 THEN
                valveCRun := FALSE;
                mixMotorRun := TRUE;
                mixCompleteLatched := FALSE;
                state := MP_MIX_C;
            END_IF;

        MP_MIX_SIMPLE:
            valveARun := FALSE;
            valveBRun := FALSE;
            valveCRun := FALSE;
            valveDRun := FALSE;
            mixMotorRun := TRUE;

            IF mixMotorComplete THEN
                mixCompleteLatched := TRUE;
            END_IF;

            IF mixCompleteLatched THEN
                mixMotorRun := FALSE;
                valveDRun := TRUE;
                state := MP_DONE;
            END_IF;

        MP_MIX_C:
