            IF mixMotorComplete THEN
                mixCompleteLatched := TRUE;
            END_IF;

            IF mixCompleteLatched THEN
                mixMotorRun := FALSE;
                valveDRun := TRUE;
                state := MP_DONE;
            END_IF;

        MP_DONE:
            valveARun := FALSE;
            valveBRun := FALSE;
            valveCRun := FALSE;
            valveDRun := TRUE;
            mixMotorRun := FALSE;
    END_CASE;
END_IF;
